func buildManualMemoryPrompt(matches []memoryloop.Match) string {
	block := memoryloop.FormatInjectionBlock(matches)
	if block == "" {
		return ""
	}
	return block + "\n\n" +
		"A relevant memory matches this prompt. Before doing substantive work, ask the user " +
