			At:   now,
		})
	}

	state.InjectionLogs = append(state.InjectionLogs, log)
	if len(state.InjectionLogs) > maxInjectionLogs {
		state.InjectionLogs = state.InjectionLogs[len(state.InjectionLogs)-maxInjectionLogs:]
	}
}

